%[text] # BEV Controller - Simulation Case
model_name = "HarnessModel_BEVController";
load_system(model_name) 

BEVController_Basic_params

set_param(model_name + "/BEV Speed Tracking Controller", ReferencedSubsystem = "BEVController_Basic_refsub");

set_param(model_name + "/Inputs", ReferencedSubsystem = "Inputs_BEVController_Random_refsub");
%[text] 
sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime = "2000");

sim_out = sim(sim_in);

simResultTimetable = extractTimetable(sim_out.logsout);
%[text] 
fig = figure; %[output:653211f0]
hold on %[output:653211f0]
grid on %[output:653211f0]
axis padded %[output:653211f0]
fig.Position(3:4) = [700 300];  % width height %[output:653211f0]

plot(simResultTimetable, "Time", "Vehicle speed input kph", LineWidth=2) %[output:653211f0]
title("Input to controller: Vehicle target speed") %[output:653211f0]
ylabel("km/h") %[output:653211f0]
fig = figure; %[output:79621401]
hold on %[output:79621401]
grid on %[output:79621401]
axis padded %[output:79621401]
fig.Position(3:4) = [700 300];  % width height %[output:79621401]

plot(simResultTimetable, "Time", "Motor torque command", LineWidth=2) %[output:79621401]
title("Output from controller: Motor torque command") %[output:79621401]
ylabel("N*m") %[output:79621401]
